_C = {}
def _rx(p):
    if p not in _C: _C[p] = re.compile(p)
    return _C[p]

def matches(t, title, place):
    """t: topic dict; title/place: Russian card title and place."""
    if _rx(t['title']).search(title or ''): return True
    pl = place or ''
    if re.search(r' [—–/] |/', pl): return False
    return bool(_rx(t.get('place') or t['title']).search(pl))
